CREATE FUNCTION [dbo].[FROOSH_MP] (@Forms___F_MENU_ANBAR___DT1 BIGINT,@Forms___F_MENU_ANBAR___DT2 BIGINT)RETURNS Table AS RETURN ( SELECT     dbo.STUF_DEF.CODE, dbo.STUF_DEF.NAME, dbo.INVO_LST.MEGHk, dbo.STUF_DEF.N_FANI, dbo.INVO_LST.MABL, dbo.INVO_LST.MABL_K, LEFT(N_FANI, 2) as col1, SUBSTRING(N_FANI,3 ,2) AS col2, SUBSTRING(N_FANI,5 ,3) AS col3, SUBSTRING(N_FANI,8 ,2) AS col4, SUBSTRING(N_FANI,10 ,1) AS col5, SUBSTRING(N_FANI,11 ,2) AS col6, dbo.HEAD_LST.DATE_N, dbo.HEAD_LST.CUST_NO, dbo.HEAD_LST.NUMBER FROM         dbo.HEAD_LST INNER JOIN    dbo.INVO_LST ON dbo.HEAD_LST.NUMBER = dbo.INVO_LST.NUMBER AND dbo.HEAD_LST.TAG = dbo.INVO_LST.TAG INNER JOIN   dbo.STUF_DEF ON dbo.INVO_LST.CODE = dbo.STUF_DEF.CODE WHERE     (dbo.HEAD_LST.TAG = 2) AND (dbo.HEAD_LST.DATE_N BETWEEN 1 AND 99999999))
